"""Receive a fictional export generated by Maestro's pinned passive projector."""

import json
from pathlib import Path
import tempfile
import unittest

from monitoring_ai.metrics import Exchange, Pricing
from monitoring_ai.server import Observatory
from monitoring_ai.source_observer import SourceObserver
from monitoring_ai.source_setup import check_selection, create_selection
from monitoring_ai.sources import load_sources
from monitoring_ai.store import Store


FIXTURE = Path(__file__).with_name("fixtures") / "maestro-passive-fictional.jsonl"


class MaestroPassiveContractTests(unittest.TestCase):
    def test_selected_export_replay_and_read_loss_retain_qualified_history(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory).resolve()
            stream = root / "selected-maestro.jsonl"
            stream.write_bytes(FIXTURE.read_bytes())
            selection = root / "private-sources.json"
            create_selection(selection, file=stream, id="maestro-file", format="normalized")

            checked = check_selection(selection)
            self.assertTrue(checked["all_readable"])
            counts = checked["checks"][0]["summary"]["records"]
            self.assertEqual((counts["usage"], counts["status"], counts["tool"]), (0, 2, 1))

            owner = SourceObserver(load_sources(selection))
            store = Store(root / "ledger.sqlite")
            observatory = Observatory(store, Pricing(None), Exchange("USD", None), source_observer=owner)
            observatory.refresh()
            first = observatory.read({})
            self.assertEqual(first["revision"], 3)
            self.assertEqual(first["source_status"]["state"], "following")
            self.assertEqual(first["source_coverage"]["inputs"][0]["latest_event_at"],
                             "2026-11-02T20:00:05.000Z")
            self.assertEqual(first["source_coverage"]["inputs"][0]["records"]["status"], 2)
            self.assertEqual(first["summary"]["total_tokens"], 0)
            self.assertNotIn("os_processes", first)
            self.assertNotIn(str(root), json.dumps(first))

            observatory.refresh()
            replay = observatory.read({})
            self.assertEqual(replay["revision"], 3)
            self.assertEqual(replay["inputs"]["inputs"][0]["replayed"], 3)

            stream.write_text(FIXTURE.read_text() + "{\"invalid\":true}\n")
            observatory.refresh()
            failed = observatory.read({})
            self.assertEqual(failed["revision"], 3)
            self.assertEqual(failed["inputs"]["inputs"][0]["state"], "unavailable")
            self.assertTrue(failed["source_coverage"]["inputs"][0]["retained"])
            stream.write_bytes(FIXTURE.read_bytes())
            observatory.refresh()
            recovered = observatory.read({})
            self.assertEqual(recovered["source_status"]["state"], "following")
            self.assertEqual(recovered["revision"], 3)


if __name__ == "__main__":
    unittest.main()
